const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modules=[['overview','◫','Overview'],['reservations','▦','Reservations'],['rooms','▤','Rooms & housekeeping'],['pos','♧','Point of sale'],['payments','▱','Payments'],['finance','▥','Finance & GST'],['people','♙','People & payroll'],['inventory','◇','Inventory'],['compliance','◎','Compliance & audit'],['messages','▧','Communications'],['reports','▥','Reports']];
const initial=[{id:'RES-2041',guest:'Aditi Sharma',type:'Deluxe King',room:204,source:'Direct',arrival:'2026-11-14',departure:'2026-11-16',status:'Confirmed'},{id:'RES-2042',guest:'Rahul Mehta',type:'Executive Suite',room:301,source:'Booking.com',arrival:'2026-11-14',departure:'2026-11-17',status:'Confirmed'},{id:'RES-2043',guest:'Sarah Wilson',type:'Premium Twin',room:208,source:'MakeMyTrip',arrival:'2026-11-14',departure:'2026-11-15',status:'Confirmed'},{id:'RES-2044',guest:'Vikram Singh',type:'Deluxe King',room:105,source:'Direct',arrival:'2026-11-12',departure:'2026-11-14',status:'In house'},{id:'RES-2045',guest:'Neha Patel',type:'Premium Twin',room:112,source:'Direct',arrival:'2026-11-13',departure:'2026-11-16',status:'In house'}];
let state;try{state=JSON.parse(localStorage.getItem('atithi-v1'))}catch{}state=state||{bookings:initial,cleaned:[],audit:[]};let current='overview',tab='arrivals',period='Week',query='',roomFilter='All';
function save(){try{localStorage.setItem('atithi-v1',JSON.stringify(state))}catch{toast('Storage unavailable. Changes only last for this session.')}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function log(message){state.audit.unshift({message,time:new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})});save()}
function kpi(title,value,unit,trend,note,icon){return `<article class="card kpi"><div class="kpi-head">${title}<span class="tileicon">${icon}</span></div><div class="kpi-value">${value}<small>${unit}</small></div><div class="trend"><strong>${trend}</strong> ${note}</div></article>`}
function head(title,sub,extra=''){return `<div class="panelhead"><div><h2>${title}</h2><p>${sub}</p></div>${extra}</div>`}
function go(id){location.hash=id;if(current===id)render()}
function filtered(){return state.bookings.filter(b=>tab==='arrivals'?b.arrival==='2026-11-14'&&b.status==='Confirmed':tab==='departures'?b.departure==='2026-11-14'&&b.status==='In house':tab==='inhouse'?b.status==='In house':true).filter(b=>(b.guest+' '+b.id+' '+b.room).toLowerCase().includes(query.toLowerCase()))}
function bookingTable(limit){const rows=filtered();return `<div class="tablewrap"><table><thead><tr><th>Guest</th><th>Room</th><th>Source</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.slice(0,limit||100).map(b=>`<tr><td><span class="guestavatar">${esc(b.guest.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span class="guestname"><b>${esc(b.guest)}</b><small>${esc(b.id)}</small></span></td><td><span class="guestname">${b.room||'Unassigned'}<small>${esc(b.type)}</small></span></td><td>${esc(b.source)}</td><td><span class="badge ${b.status==='Confirmed'?'amber':''}">${b.status}</span></td><td>${b.status==='Confirmed'?`<button class="action" data-check="${b.id}">Check in →</button>`:b.status==='In house'?`<button class="action" data-check="${b.id}">Check out →</button>`:'—'}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No reservations match this view.</div>':''}</div><div class="table-foot"><span>${Math.min(limit||100,rows.length)} of ${rows.length} reservations</span><button class="link" data-go="reservations">View all reservations ↗</button></div>`}
function tabs(){return `<div class="tabs">${[['arrivals','Arrivals'],['departures','Departures'],['inhouse','In house'],...(current==='reservations'?[['all','All bookings']]:[])].map(([id,label])=>`<button class="${tab===id?'active':''}" data-tab="${id}">${label}<span>${state.bookings.filter(b=>id==='arrivals'?b.arrival==='2026-11-14'&&b.status==='Confirmed':id==='departures'?b.departure==='2026-11-14'&&b.status==='In house':id==='inhouse'?b.status==='In house':true).length}</span></button>`).join('')}</div>`}
function chart(){const vals=period==='Week'?[46,62,53,85,70,100,89]:[58,78,66,96,83,110,100];return `<svg viewBox="0 0 570 170" role="img" aria-label="Illustrative room and other revenue chart"><g stroke="#edf0e9" stroke-dasharray="3 4">${[22,58,94,130].map(y=>`<path d="M45 ${y}H555"/>`).join('')}</g>${['₹60k','₹40k','₹20k','₹0'].map((v,i)=>`<text x="2" y="${26+i*36}">${v}</text>`).join('')}${vals.map((v,i)=>`<rect x="${68+i*72}" y="${130-v}" width="17" height="${v}" rx="3" fill="#63856a"/><rect x="${89+i*72}" y="${130-v*.45}" width="17" height="${v*.45}" rx="3" fill="#cad9b9"/><text x="${72+i*72}" y="154">${period==='Week'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]:['1–4','5–8','9–12','13–16','17–20','21–24','25–30'][i]}</text>`).join('')}</svg>`}
function overview(){return `<div class="kpis">${kpi('Room occupancy','72','/ 100 rooms','↗ 8.2%','vs. last week','▤')}${kpi("Today's revenue",'₹2,84,650','','↗ 12.6%','vs. yesterday','₹')}${kpi('Expected arrivals',state.bookings.filter(b=>b.arrival==='2026-11-14'&&b.status==='Confirmed').length,'guests','Ready to welcome','today’s reservations','↙')}${kpi('Expected departures',state.bookings.filter(b=>b.departure==='2026-11-14'&&b.status==='In house').length,'guests','Late checkout','requests: 0','↗')}</div><div class="mainrow"><section class="card">${head('Revenue overview','A good week for great hospitality.',`<div class="segmented"><button data-period="Week" class="${period==='Week'?'active':''}">This week</button><button data-period="Month" class="${period==='Month'?'active':''}">This month</button></div>`)}<div class="revenue-total"><b>${period==='Week'?'₹18,42,500':'₹64,28,900'}</b><span class="pill">↗ ${period==='Week'?'14.8':'11.2'}%</span></div><div class="chart">${chart()}</div><div class="legend"><span><i class="dot"></i>Room revenue</span><span><i class="dot light"></i>F&B and other services</span></div></section><section class="card">${head('Room status','Every room, accounted for.','<button class="link" data-go="rooms">View rooms ↗</button>')}<div class="room-summary"><div class="donut"><div class="donut-inner"><b>100</b><span>Total rooms</span></div></div><div class="roomlegend">${[['Occupied','72','#3b715b'],['Available','15','#b6cba5'],['Cleaning','8','#ecd5a7'],['Maintenance','5','#e7ebe5']].map(([l,n,c])=>`<div><span><i class="dot" style="background:${c}"></i>${l}</span><b>${n}</b></div>`).join('')}</div></div><div class="room-foot"><span>◷ Housekeeping overview</span><button class="link" data-go="rooms">Manage rooms →</button></div></section></div><div class="lowerrow"><section class="card">${head('Guest activity','Make every arrival feel like a welcome.','<button class="link" data-export="reservations">Export ↓</button>')}${tabs()}${bookingTable(3)}</section><section class="card">${head('Needs your attention','A few things to keep the day running.','<span class="badge amber">3 items</span>')}${task('◷','Settlement reconciliation','2 payment batches awaiting review','payments','Review')}${task('▧','GST filing workspace','Review draft return data with your CA','compliance','View')}${task('◇','Inventory running low','3 items below reorder level','inventory','View')}<div class="table-foot"><span>Keep your operations a step ahead.</span></div></section></div><div class="quicklinks">${[['pos','♧','Open point of sale','Restaurant, spa & more'],['people','♙','People & payroll','Take care of your team'],['finance','▧','GST & finance','Keep your books in order'],['reports','▥','Property reports','Turn insights into action']].map(([id,icon,t,s])=>`<button data-go="${id}"><span>${icon}</span><span>${t}<small>${s}</small></span><span>↗</span></button>`).join('')}</div>`}
function task(icon,title,sub,target,action){return `<div class="task"><span class="task-icon">${icon}</span><div><h3>${title}</h3><p>${sub}</p></div><button class="link" data-go="${target}">${action} →</button></div>`}
const catalogs={pos:[['Restaurant','₹34,820','12 open tables · 28 orders'],['Spa & wellness','₹12,500','5 appointments today'],['Laundry','₹4,200','8 guest folios']],payments:[['Razorpay','₹1,84,200','Sample batch · Reconciliation pending'],['Cashfree','₹64,500','Sample batch · Reconciliation pending'],['Offline collections','₹35,950','Cash and bank transfer register']],finance:[['Revenue ledger','₹18,42,500','Illustrative weekly revenue'],['Accounts receivable','₹2,14,800','7 guest and corporate balances'],['Accounts payable','₹1,36,250','5 vendor invoices awaiting review']],people:[['On duty today','42 / 56','Front desk, F&B, housekeeping and security'],['Payroll draft','₹12,48,500','November 2026 · Not processed'],['Leave requests','4 pending','2 annual leave · 2 casual leave']],inventory:[['Bath towels','24 units','Reorder level: 40 units'],['Basmati rice','18 kg','Reorder level: 25 kg'],['Guest toiletries','32 kits','Reorder level: 50 kits']],compliance:[['GST returns','Draft workspace','GSTR-1 / GSTR-3B · CA review required'],['Guest compliance','Review queue','FRRO / C-Form integration not connected'],['Payroll compliance','Rules pending','PF, ESI, PT and salary TDS configuration']],messages:[['Reservation confirmations','12 drafts','Email · Templates ready for review'],['Guest welcome','8 drafts','WhatsApp · Provider not connected'],['Payment receipts','6 drafts','SMS · Provider not connected']]};
function moduleView(){return `<div class="report-note">${current==='compliance'?'Compliance review workspace. Tax rules must be effective-dated and verified for the property before use. No statutory returns are submitted by this demo.':current==='payments'?'Payment sandbox preview. Gateways are not connected; no live charges, refunds or settlements are executed.':'Illustrative operations workspace · Connect your backend to use live property data.'}</div><div class="module-grid">${catalogs[current].map(([t,v,s],i)=>`<article class="card"><span class="eyebrow">${current.toUpperCase()}</span><h2 style="margin-top:16px">${t}</h2><div class="kpi-value">${v}</div><p>${s}</p><button class="outline" data-detail="${i}">View details →</button></article>`).join('')}</div><section class="card">${head(current==='compliance'?'Activity & audit trail':'Workspace activity','Local demo activity; production requires server-side immutable logs.')}<div style="padding:20px">${state.audit.length?state.audit.slice(0,15).map(a=>`<p class="muted">${esc(a.time)} — ${esc(a.message)}</p>`).join(''):'<p class="muted">Your reservation and housekeeping actions will appear here.</p>'}</div></section>`}
function roomStatus(i){return state.cleaned.includes(i)?'Available':i<=72?'Occupied':i<=87?'Available':i<=95?'Cleaning':'Maintenance'}
function rooms(){return `<div class="report-note">100-room property overview. Housekeeping actions below update this device's demo room records.</div><div class="toolbar"><select id="roomFilter" aria-label="Filter room status">${['All','Occupied','Available','Cleaning','Maintenance'].map(s=>`<option ${roomFilter===s?'selected':''}>${s}</option>`).join('')}</select><button class="outline" data-export="rooms">Export rooms ↓</button></div><div class="rooms">${Array.from({length:100},(_,i)=>i+1).filter(i=>roomFilter==='All'||roomStatus(i)===roomFilter).map(i=>`<article class="room"><h3>${100+i}</h3><span class="badge ${roomStatus(i)==='Cleaning'?'amber':''}">${roomStatus(i)}</span><p>${i%3===0?'Premium Twin':'Deluxe King'}</p>${roomStatus(i)==='Cleaning'?`<button class="action" data-clean="${i}">Mark clean ✓</button>`:''}</article>`).join('')}</div>`}
function reports(){return `<div class="report-note"><b>Implementation roadmap:</b> Your brief says 24 weeks, while its phase table says 24 days. Use a 24-week planning baseline until scope and staffing are confirmed. This dashboard is the interactive frontend prototype.</div><div class="module-grid">${[['Reservations register','Guest, room, dates, source and status','reservations'],['Room inventory','100 rooms and housekeeping status','rooms'],['Activity register','Actions recorded in this browser','audit']].map(([t,s,id])=>`<article class="card"><h2>${t}</h2><p>${s}</p><button class="primary" data-export="${id}">Download CSV ↓</button></article>`).join('')}</div><section class="card">${head('Delivery plan','Suggested allocation across 24 weeks')}<div style="padding:22px;line-height:2.5">${['Weeks 1–3 · Discovery, SRS, architecture and data model','Weeks 4–8 · Reservations, front desk, housekeeping and inventory','Weeks 9–13 · Payment integrations, financial ledger and tax engine','Weeks 14–17 · HR, payroll, RBAC and audit trails','Weeks 18–19 · Messaging and channel manager integrations','Weeks 20–21 · UAT, security review and load testing','Weeks 22–24 · Migration, pilot, training and go-live'].map(s=>`<div>${s}</div>`).join('')}</div></section>`}
function render(){current=location.hash.slice(1)||'overview';if(!modules.some(m=>m[0]===current))current='overview';$('#nav').innerHTML=modules.map(([id,icon,t])=>`<button title="${t}" data-go="${id}" class="${id===current?'active':''}"><span class="navicon">${icon}</span><span class="navtext">${t}</span>${id==='compliance'?'<span class="navcount">3</span>':''}</button>`).join('');const name=modules.find(m=>m[0]===current)[2];$('#crumb').textContent=name;$('#title').innerHTML=current==='overview'?'Good morning, Arjun <span class="sun">☀</span>':name;$('#subtitle').textContent=current==='overview'?"Here's what's happening at The Grand Pavilion today.":'The Grand Pavilion · Jaipur, Rajasthan';$('#content').innerHTML=current==='overview'?overview():current==='reservations'?`<div class="toolbar"><input id="search" aria-label="Search reservations" placeholder="Search guest, reservation or room…" value="${esc(query)}"><button class="outline" data-export="reservations">Export CSV ↓</button></div><section class="card">${head('Reservation register','Guest stays and front desk actions')}${tabs()}<div id="table">${bookingTable()}</div></section>`:current==='rooms'?rooms():current==='reports'?reports():moduleView()}
function download(kind){let rows=kind==='reservations'?[['ID','Guest','Room type','Room','Source','Arrival','Departure','Status'],...state.bookings.map(b=>[b.id,b.guest,b.type,b.room,b.source,b.arrival,b.departure,b.status])]:kind==='rooms'?[['Room','Status'],...Array.from({length:100},(_,i)=>[101+i,roomStatus(i+1)])]:[['Time','Action'],...state.audit.map(a=>[a.time,a.message])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`atithi-${kind}-2026-11-14.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV report downloaded')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go)go(b.dataset.go);if(b.dataset.tab){tab=b.dataset.tab;render()}if(b.dataset.period){period=b.dataset.period;render()}if(b.dataset.export)download(b.dataset.export);if(b.dataset.check){const r=state.bookings.find(r=>r.id===b.dataset.check);if(r.status==='Confirmed'){if(!r.room){const used=state.bookings.filter(x=>x.status!=='Checked out').map(x=>x.room);r.room=Array.from({length:15},(_,i)=>173+i).find(n=>!used.includes(n));if(!r.room){toast('No available demo rooms. Please review room inventory.');return}}r.status='In house'}else r.status='Checked out';log(`${r.guest}: ${r.status}`);render();toast(`${r.guest} ${r.status==='In house'?'checked in':'checked out'} successfully`)}if(b.dataset.clean){state.cleaned.push(Number(b.dataset.clean));log(`Room ${100+Number(b.dataset.clean)} marked clean`);render();toast('Room marked available')}if(b.dataset.detail!==undefined){const item=catalogs[current][Number(b.dataset.detail)];toast(`${item[0]}: ${item[2]}. Live backend integration pending.`)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#table').innerHTML=bookingTable()}});document.addEventListener('change',e=>{if(e.target.id==='roomFilter'){roomFilter=e.target.value;render()}});
$('#newbooking').onclick=()=>$('#modal').showModal();$('#closemodal').onclick=()=>$('#modal').close();$('#bookingform').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.guest.trim()){toast('Enter a guest name');return}if(d.departure<=d.arrival){toast('Check-out must be after check-in');return}const id='RES-'+Date.now().toString().slice(-7);state.bookings.unshift({...d,guest:d.guest.trim(),id,room:null,status:'Confirmed'});log(`Reservation ${id} created for ${d.guest.trim()}`);$('#modal').close();e.target.reset();tab='all';go('reservations');toast('Reservation created successfully')};$('#notifications').onclick=()=>go('compliance');$('#guide').onclick=()=>go('reports');$('#profile').onclick=()=>toast('Arjun Kapoor · Demo property administrator');window.addEventListener('hashchange',render);render();
